    act={(i,j) for i in range(H) for j in range(W) if gi[i][j]==bg and gio[i][j]==fill}
    def inrun(i,j,hv):
        # hv='r' row-run, 'c' col-run: returns True if run bounded by fill on both ends
        if hv=='r':
            lo=[a for a in range(j) if gi[i][a]==fill][-1] if any(gi[i][a]==fill for a in range(j)) else None
            hi=[b for b in range(j+1,W) if gi[i][b]==fill][0] if any(gi[i][b]==fill for b in range(j+1,W)) else None
            return lo is not None and hi is not None
        else:
            lo=[a for a in range(i) if gi[a][j]==fill][-1] if any(gi[a][j]==fill for a in range(i)) else None
            hi=[b for b in range(i+1,H) if gi[b][j]==fill][0] if any(gi[b][j]==fill for b in range(i+1,H)) else None
            return lo is not None and hi is not None
    def preds(cell,hv):
        i,j_=cell; out=[]
        if inrun(i,j_,'r'): out.append('r')
        if inrun(i,j_,'c'): out.append('c')
        return tuple(out)
